{"path": "./api/products.go", "content": "package api

import (
    "database/sql"
    "encoding/json"
    "net/http"
    "strconv"
)

type Product struct {
    ID    int     `json:"id"`
    Name  string  `json:"name"`
    Price float64 `json:"price"`
    Stock int     `json:"stock"`
}

type ProductsResponse struct {
    Products []Product `json:"products"`
    Total    int      `json:"total"`
    Page     int      `json:"page"`
    PageSize int      `json:"pageSize"`
}

func GetProductsHandler(db *sql.DB) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        // Get pagination parameters with defaults
        page := 1
        pageSize := 20

        if p := r.URL.Query().Get("page"); p != "" {
            if val, err := strconv.Atoi(p); err == nil && val > 0 {
                page = val
            }
        }

        if ps := r.URL.Query().Get("pageSize"); ps != "" {
            if val, err := strconv.Atoi(ps); err == nil && val > 0 && val <= 100 {
                pageSize = val
            }
        }

        var products []Product
        var total int

        // Get total count
        err := db.QueryRow("SELECT COUNT(*) FROM products").Scan(&total)
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }

        // Handle requests without pagination (backwards compatible)
        if r.URL.Query().Get("page") == "" && r.URL.Query().Get("pageSize") == "" {
            rows, err := db.Query("SELECT id, name, price, stock FROM products")
            if err != nil {
                http.Error(w, err.Error(), http.StatusInternalServerError)
                return
            }
            defer rows.Close()

            for rows.Next() {
                var p Product
                if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock); err != nil {
                    http.Error(w, err.Error(), http.StatusInternalServerError)
                    return
                }
                products = append(products, p)
            }

            w.Header().Set("Content-Type", "application/json")
            json.NewEncoder(w).Encode(products)
            return
        }

        // Paginated query
        offset := (page - 1) * pageSize
        rows, err := db.Query("SELECT id, name, price, stock FROM products ORDER BY id LIMIT $1 OFFSET $2", pageSize, offset)
        if err != nil {
            http.Error(w, err.Error(), http.StatusInternalServerError)
            return
        }
        defer rows.Close()

        for rows.Next() {
            var p Product
            if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Stock); err != nil {
                http.Error(w, err.Error(), http.StatusInternalServerError)
                return
            }
            products = append(products, p)
        }

        response := ProductsResponse{
            Products: products,
            Total:    total,
            Page:     page,
            PageSize: pageSize,
        }

        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(response)
    }
}"}

