@Aspect
@Component
public class RateLimiterAspect {
    private static final String RATE_LIMIT_SCRIPT = "local current = redis.call('incr', KEYS[1])
if tonumber(current) == 1 then
    redis.call('expire', KEYS[1], ARGV[1])
end
return current";

    private final RedisTemplate<String, Object> redisTemplate;

    public RateLimiterAspect(RedisTemplate<String, Object> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    @Around("@annotation(rateLimited)")
    public Object rateLimit(ProceedingJoinPoint joinPoint, RateLimited rateLimited) throws Throwable {
        HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest();
        String clientIp = request.getHeader("X-Forwarded-For");
        if (clientIp == null) {
            clientIp = request.getRemoteAddr();
        }

        String key = "rate_limit:" + clientIp;
        RedisScript<Long> script = RedisScript.of(RATE_LIMIT_SCRIPT, Long.class);
        Long count = redisTemplate.execute(script, Collections.singletonList(key), String.valueOf(60));

        if (count != null && count > 600) { // 500 normal + 100 burst
            throw new RuntimeException("Rate limit exceeded");
        }

        return joinPoint.proceed();
    }
